// Profile image data URI from Shahd Mohamed Teleba's original portfolio
window.SHAHD_PHOTO_URI = "data:image/jpeg;base64,";
document.addEventListener('DOMContentLoaded', function() {
  var img = document.getElementById('shahdProfileImg');
  if (img && window.SHAHD_PHOTO_URI) {
    img.src = window.SHAHD_PHOTO_URI;
  }
});
